<script setup>
const route=useRoute(),{user,send,busy,fa}=useReiki()
const {data:item,error}=await useFetch('/api/catalog/content',{query:{id:route.params.id}})
const {data:favs}=await useFetch('/api/account/favorites',{immediate:!!user.value,default:()=>[]})
const {data:progress}=await useFetch('/api/account/progress',{immediate:!!user.value,default:()=>[]})
const count=ref(progress.value?.find(p=>p.subject_kind==='mantra'&&p.subject_id===Number(route.params.id))?.position_sec||0),target=ref(27)
const saved=computed(()=>favs.value?.some(f=>f.id===item.value?.id))
async function favorite(){if(!user.value)return navigateTo('/profile');if(await send('/api/account/favorites',{id:item.value.id,saved:!saved.value}))await refreshNuxtData()}
async function saveCount(){if(!user.value)return navigateTo('/profile');await send('/api/account/progress',{kind:'mantra',id:item.value.id,position:count.value})}
async function purchase(){if(!user.value)return navigateTo('/profile');await send('/api/account/purchases',{kind:'content',id:item.value.id})}
const labels={script:'متن اصلی',translit:'تلفظ فارسی',meaning:'معنی',usage:'روش تمرین',pattern:'الگوی تنفس'}
useHead({title:computed(()=>item.value?.title||'محتوا')})
</script>
<template><main class="page"><NuxtLink to="/discover" class="back">→ بازگشت به کشف</NuxtLink><div v-if="error" class="state">محتوا یافت نشد یا ارتباط قطع است.</div><template v-if="item"><div class="page-heading"><small>{{item.type_title}}</small><h1>{{item.title}}</h1><p>{{item.summary}}</p></div><button class="btn btn-ghost" :aria-pressed="saved" :disabled="busy" @click="favorite">{{saved?'♥ در علاقه‌مندی‌ها':'♡ افزودن به علاقه‌مندی‌ها'}}</button><section v-if="!item.access.allowed" class="card lock-card section"><AppIcon name="moon"/><h2>این بخش برای تو هنوز باز نشده</h2><p>{{item.access_type==='premium'?'با عضویت ویژه به این محتوا دسترسی خواهی داشت.':item.access_type==='course'?'این محتوا فقط با دسترسی به دوره باز می‌شود؛ عضویت ویژه کافی نیست.':'این محتوا به دسترسی جداگانه نیاز دارد.'}}</p><NuxtLink v-if="!user" to="/profile" class="btn btn-primary">ورود یا ساخت حساب</NuxtLink><NuxtLink v-else-if="item.access_type==='premium'" to="/premium" class="btn btn-gold">مشاهدهٔ عضویت ویژه</NuxtLink><NuxtLink v-else-if="item.access_type==='course'" :to="'/courses/'+item.course_id" class="btn btn-gold">مشاهدهٔ دوره</NuxtLink><button v-else-if="item.access_type==='individual'" class="btn btn-gold" :disabled="busy" @click="purchase">درخواست خرید · {{fa(item.price)}} تومان</button><p v-else>برای دسترسی اختصاصی با مدیر هماهنگ کن.</p></section><template v-else><article class="prose section">{{item.body}}</article><section v-for="(label,key) in labels" :key="key" class="section"><template v-if="item.payload?.[key]"><h3>{{label}}</h3><p class="prose" :dir="key==='script'?'auto':'rtl'">{{item.payload[key]}}</p></template></section><section v-if="item.type==='mantra'" class="card counter"><h2>شمارندهٔ مانترا</h2><div class="row filters"><button v-for="n in [27,54,108]" :key="n" class="chip" :aria-pressed="target===n" @click="target=n">{{fa(n)}}</button></div><label class="field"><span>هدف دلخواه</span><input v-model.number="target" class="input" type="number" min="1" max="100000"/></label><button class="counter-tap" aria-label="یک تکرار اضافه کن" @click="count++">{{fa(count)}}<small>از {{fa(target)}} · لمس کن</small></button><div class="row"><button class="btn btn-primary" :disabled="busy" @click="saveCount">ذخیرهٔ شمارش</button><button class="btn btn-ghost" @click="count=0">از نو</button></div></section><p v-if="item.type==='meditation'" class="card">این مراقبه فعلاً نسخهٔ متنی نمونه است؛ فایل صوتی واقعی هنوز بارگذاری نشده است.</p><p class="disclaimer">نگاه سنتی و معنوی، نه ادعای درمانی. در صورت ناراحتی تمرین را متوقف کن.</p></template></template></main></template>
